from typing import List, Sequence, Tuple, Dict

def downsample(points: Sequence[Tuple[int, float]], bucket_seconds: int, agg: str = "mean") -> List[Tuple[int, float]]:
    if bucket_seconds < 1:
        raise ValueError("bucket_seconds must be >= 1")
    valid_aggs = {"mean", "max", "sum", "last"}
    if agg not in valid_aggs:
        raise ValueError(f"agg must be one of {valid_aggs}")
    if not points:
        return []

    buckets: Dict[int, List[Tuple[int, float]]] = {}
    for ts, val in points:
        b_start = ts - (ts % bucket_seconds)
        buckets.setdefault(b_start, []).append((ts, val))

    result = []
    for b_start in sorted(buckets.keys()):
        pts = buckets[b_start]
        if agg == "mean":
            v = round(sum(p[1] for p in pts) / len(pts), 2)
        elif agg == "max":
            v = max(p[1] for p in pts)
        elif agg == "sum":
            v = sum(p[1] for p in pts)
        elif agg == "last":
            v = max(pts, key=lambda p: p[0])[1]
        result.append((b_start, v))
    return result"
    }
  },
  "messages": []
}
